update lessons set objective_ar='أحلّل قصة «أحلام طفلة» للكاتبة الإماراتية صالحة غابش إلى عناصرها، وأحدّد وجهة نظر الراوي وأثرها، وأوازن بينها وبين قصص المجموعة القصصية «كلنا كلنا نحب البحر».' where code='AR-Y8-N-T3-L02';
update success_criteria set statement_ar='أحدّد الشخصية والإطار وحلم الطفلة.' where sort_order=1 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L02');
update success_criteria set statement_ar='أحلّل وجهة نظر الراوي واللغة الشاعرية.' where sort_order=2 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L02');
update success_criteria set statement_ar='أكتب استجابة شخصية عن حلم الطفلة بالتعلّم، داعمًا رأيي بالأدلة.' where sort_order=3 and lesson_id=(select id from lessons where code='AR-Y8-N-T3-L02');
update lesson_summaries set content=content||'{"hook": "طفلة تحلم بالمدرسة… وأبوها يقول: المدرسة بعيدة. ماذا تفعل الأحلام؟", "idea": "قصة من المجموعة القصصية «كلنا كلنا نحب البحر» تروي حلم طفلة بالذهاب إلى المدرسة، وصراعها مع رأي أبيها، بلغة شاعرية.", "learn": [["📖", "أقرأ القصة في كتابي ص 32–33."], ["🎒", "حلم الطفلة: المدرسة وصديقات جديدات."], ["🚧", "الأب: المدرسة بعيدة، وخير لها أن تساعد في البيت."], ["🔎", "الكاتبة شاعرة أيضًا، فتظهر الصور والإيقاع في سردها."], ["💡", "أطبّق المهارة وأربطها بحياتي."]]}'::jsonb where lesson_id=(select id from lessons where code='AR-Y8-N-T3-L02');